"""Readable trace of a replay request using the (verified) reference engine."""
import json, sys
from ref_replay import ref_replay

def kindname(k): return k

def trace(req):
    P = len(req["inputs"]); R = len(req["inputs"][0]) if P else 0
    inputs = req["inputs"]; nslots = req["slots"]; window = req["window"]
    events = req["events"]
    # replay with logging: run the reference but with a hook
    sent = {r: 0 for r in range(P)}
    received = {r: [] for r in range(P)}
    floor = 0
    up_next = {r: 0 for r in range(P)}
    acked = {r: 0 for r in range(P)}
    phys = [None] * nslots
    packets = {}
    nxt = 0
    ident = {}
    def desc(i):
        p = packets[i]
        return "%s(r%d,q=%s,v=%s)" % (p["kind"], p["rank"], p["seq"], p["value"])
    for ev in events:
        print("event", ev)
        if ev[0] == "send":
            _, r, q = ev
            if sent[r] <= q < min(R, sent[r] + window):
                packets[nxt] = {"id": nxt, "kind": "up", "rank": r, "seq": q, "value": list(inputs[r][q])}
                nxt += 1
                print("   -> create", desc(nxt-1), "host sent=%d" % sent[r])
            else:
                print("   disabled")
        elif ev[0] == "retry":
            _, r = ev
            for t in sorted([t for t in phys if t is not None and len(t[1]) == P and t[0] >= acked[r]]):
                packets[nxt] = {"id": nxt, "kind": "down", "rank": r, "seq": t[0], "value": list(t[2])}
                nxt += 1
                print("   -> create", desc(nxt-1))
        else:
            pid = ev[1]
            if pid not in packets:
                print("   missing")
                continue
            pk = packets[pid]
            print("   packet", desc(pid))
            if ev[0] == "drop":
                del packets[pid]; print("   dropped"); continue
            if ev[0] == "duplicate":
                packets[nxt] = {"id": nxt, "kind": pk["kind"], "rank": pk["rank"], "seq": pk["seq"], "value": pk["value"]}
                nxt += 1; print("   -> copy", desc(nxt-1)); continue
            del packets[pid]
            k, r, seq, val = pk["kind"], pk["rank"], pk["seq"], pk["value"]
            if k == "up":
                if floor <= seq < floor + nslots:
                    p = seq % nslots
                    cur = phys[p]
                    if cur is None or cur[0] != seq:
                        phys[p] = (seq, {r}, list(val)); nf = len({r}) == P
                        print("   new slot entry q=%d ranks=%s sum=%s" % (seq, {r}, list(val)))
                    else:
                        ranks, s = cur[1], cur[2]
                        if r in ranks:
                            nf = False; print("   duplicate contribution ignored")
                        else:
                            ranks.add(r)
                            for i in range(len(s)): s[i] += val[i]
                            nf = len(ranks) == P
                            print("   add rank %d -> ranks=%s sum=%s" % (r, sorted(ranks), list(s)))
                    while True:
                        t = phys[up_next[r] % nslots]
                        if t is not None and t[0] == up_next[r] and r in t[1]:
                            up_next[r] += 1
                        else: break
                    packets[nxt] = {"id": nxt, "kind": "uack", "rank": r, "seq": up_next[r], "value": None}; nxt += 1
                    print("   -> uack", desc(nxt-1), " (up_next[%d]=%d)" % (r, up_next[r]))
                    if nf:
                        t = phys[seq % nslots]
                        for rr in range(P):
                            packets[nxt] = {"id": nxt, "kind":"down","rank":rr,"seq":seq,"value":list(t[2])}; nxt += 1
                            print("   -> down", desc(nxt-1))
                else:
                    packets[nxt] = {"id": nxt, "kind":"uack","rank":r,"seq":up_next[r],"value":None}; nxt += 1
                    print("   out of window [floor=%d,%d) -> negative/unchanged uack" % (floor, floor+nslots), desc(nxt-1))
            elif k == "uack":
                sent[r] = max(sent[r], seq); print("   sent[%d]=%d" % (r, sent[r]))
            elif k == "down":
                if seq == len(received[r]):
                    received[r].append(val); print("   received[%d] += %s" % (r, val))
                else:
                    print("   DISCARD out-of-order (q=%d, len=%d)" % (seq, len(received[r])))
                packets[nxt] = {"id": nxt, "kind":"dack","rank":r,"seq":len(received[r]),"value":None}; nxt += 1
                print("   -> dack", desc(nxt-1))
            else:
                acked[r] = max(acked[r], seq)
                floor = min(acked.values())
                for i in range(nslots):
                    t = phys[i]
                    if t is not None and t[0] < floor:
                        print("   release slot entry q=%d" % t[0]); phys[i] = None
                print("   acked=%s -> floor=%d" % (acked, floor))
        print("   pending:", sorted(packets), "buf:", sorted([(t[0], sorted(t[1]), t[2]) for t in phys if t is not None]))
    print("final hosts:", [(sent[r], received[r]) for r in range(P)], "floor:", floor)

if __name__ == "__main__":
    req = json.load(open(sys.argv[1]))
    trace(req)
PYEOF
